static int asn1_decode_entry(sc_context_t *ctx,struct sc_asn1_entry *entry,
                             const u8 *obj, size_t objlen, int depth)
{
        void *parm = entry->parm;
        int (*callback_func)(sc_context_t *nctx, void *arg, const u8 *nobj,
                             size_t nobjlen, int ndepth);
        size_t *len = (size_t *) entry->arg;
        int r = 0;

        callback_func = parm;

        sc_debug(ctx, SC_LOG_DEBUG_ASN1, "%*.*sdecoding '%s', raw data:%s%s\n",
                depth, depth, "", entry->name,
                sc_dump_hex(obj, objlen > 16  ? 16 : objlen),
                objlen > 16 ? "..." : "");

        switch (entry->type) {
        case SC_ASN1_STRUCT:
                if (parm != NULL)
                        r = asn1_decode(ctx, (struct sc_asn1_entry *) parm, obj,
                                       objlen, NULL, NULL, 0, depth + 1);
                break;
        case SC_ASN1_NULL:
                break;
        case SC_ASN1_BOOLEAN:
                if (parm != NULL) {
                        if (objlen != 1) {
                                sc_debug(ctx, SC_LOG_DEBUG_ASN1,
                                         "invalid ASN.1 object length: %"SC_FORMAT_LEN_SIZE_T"u\n",
                                         objlen);
                                r = SC_ERROR_INVALID_ASN1_OBJECT;
                        } else
                                *((int *) parm) = obj[0] ? 1 : 0;
                }
                break;
        case SC_ASN1_INTEGER:
        case SC_ASN1_ENUMERATED:
                if (parm != NULL) {
                        r = sc_asn1_decode_integer(obj, objlen, (int *) entry->parm, 0);
                        sc_debug(ctx, SC_LOG_DEBUG_ASN1, "%*.*sdecoding '%s' returned %d\n", depth, depth, "",
                                        entry->name, *((int *) entry->parm));
                }
                break;
        case SC_ASN1_BIT_STRING_NI:
        case SC_ASN1_BIT_STRING:
                if (parm != NULL) {
                        int invert = entry->type == SC_ASN1_BIT_STRING ? 1 : 0;
                        assert(len != NULL);
                        if (objlen < 1) {
                                r = SC_ERROR_INVALID_ASN1_OBJECT;
                                break;
                        }
                        if (entry->flags & SC_ASN1_ALLOC) {
                                u8 **buf = (u8 **) parm;
                                if (objlen > 1) {
                                        *buf = malloc(objlen-1);
                                        if (*buf == NULL) {
                                                r = SC_ERROR_OUT_OF_MEMORY;
                                                break;
                                        }
                                }
                                *len = objlen-1;
                                parm = *buf;
                        }
                        r = decode_bit_string(obj, objlen, (u8 *) parm, *len, invert);
                        if (r >= 0) {
                                *len = r;
                                r = 0;
                        }
                }
                break;
        case SC_ASN1_BIT_FIELD:
                if (parm != NULL)
                        r = decode_bit_field(obj, objlen, (u8 *) parm, *len);
                break;
        case SC_ASN1_OCTET_STRING:
                if (parm != NULL) {
                        size_t c;
                        assert(len != NULL);

                        /* Strip off padding zero */
                        if ((entry->flags & SC_ASN1_UNSIGNED)
                                        && objlen > 1 && obj[0] == 0x00) {
                                objlen--;
                                obj++;
                        }

                        /* Allocate buffer if needed */
                        if (entry->flags & SC_ASN1_ALLOC) {
                                u8 **buf = (u8 **) parm;
                                if (objlen > 0) {
                                        *buf = malloc(objlen);
                                        if (*buf == NULL) {
                                                r = SC_ERROR_OUT_OF_MEMORY;
                                                break;
                                        }
                                }
                                c = *len = objlen;
                                parm = *buf;
                        } else
                                c = objlen > *len ? *len : objlen;

                        memcpy(parm, obj, c);
                        *len = c;
                }
                break;
        case SC_ASN1_GENERALIZEDTIME:
                if (parm != NULL) {
                        size_t c;
                        assert(len != NULL);
                        if (entry->flags & SC_ASN1_ALLOC) {
                                u8 **buf = (u8 **) parm;
                                if (objlen > 0) {
                                        *buf = malloc(objlen);
                                        if (*buf == NULL) {
                                                r = SC_ERROR_OUT_OF_MEMORY;
                                                break;
                                        }
                                }
                                c = *len = objlen;
                                parm = *buf;
                        } else
                                c = objlen > *len ? *len : objlen;

                        memcpy(parm, obj, c);
                        *len = c;
                }

int sc_asn1_decode_integer(const u8 * inbuf, size_t inlen, int *out, int strict)
{
        int    a = 0, is_negative = 0;
        size_t i = 0;

        if (inlen == 0) {
                return SC_ERROR_INVALID_ASN1_OBJECT;
        }
        if (inlen > sizeof(int)) {
                return SC_ERROR_NOT_SUPPORTED;
        }
        if (inbuf[0] & 0x80) {
                if (strict && inlen > 1 && inbuf[0] == 0xff && (inbuf[1] & 0x80)) {
                        return SC_ERROR_INVALID_ASN1_OBJECT;
                }
                is_negative = 1;
                a |= 0xff^(*inbuf++);
                i = 1;
        } else {
                if (strict && inlen > 1 && inbuf[0] == 0x00 && (inbuf[1] & 0x80) == 0) {
                        return SC_ERROR_INVALID_ASN1_OBJECT;
                }
        }
        for (; i < inlen; i++) {
                if (a > (INT_MAX >> 8) || a < (INT_MIN + (1<<8))) {
                        return SC_ERROR_NOT_SUPPORTED;
                }
                a <<= 8;
                if (is_negative) {
                        a |= 0xff^(*inbuf++);
                } else {
                        a |= *inbuf++;
                }
        }
        if (is_negative) {
                /* Calculate Two's complement from previously positive number */
                a = (-1 * a) - 1;
        }
        *out = a;
        return 0;
}

sc_pkcs15_parse_unusedspace(const unsigned char *buf, size_t buflen, struct sc_pkcs15_card *p15card)
{
        const unsigned char *p = buf;
        size_t left = buflen;
        int r;
        struct sc_path path;
        struct sc_pkcs15_id auth_id;
        struct sc_asn1_entry asn1_unusedspace[] = {
                { "UnusedSpace", SC_ASN1_STRUCT, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, NULL, NULL },
                { NULL, 0, 0, 0, NULL, NULL }
        };
        struct sc_asn1_entry asn1_unusedspace_values[] = {
                { "path", SC_ASN1_PATH, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, NULL, NULL },
                { "authId", SC_ASN1_PKCS15_ID, SC_ASN1_TAG_OCTET_STRING, SC_ASN1_OPTIONAL, NULL, NULL },
                { NULL, 0, 0, 0, NULL, NULL }
        };

        /* Clean the list if already present */
        sc_pkcs15_free_unusedspace(p15card);

        sc_format_asn1_entry(asn1_unusedspace, asn1_unusedspace_values, NULL, 1);
        sc_format_asn1_entry(asn1_unusedspace_values, &path, NULL, 1);
        sc_format_asn1_entry(asn1_unusedspace_values+1, &auth_id, NULL, 0);

        while (left > 0) {
                memset(&auth_id, 0, sizeof(auth_id));
                r = sc_asn1_decode(p15card->card->ctx, asn1_unusedspace, p, left, &p, &left);
                if (r == SC_ERROR_ASN1_END_OF_CONTENTS)
                        break;
